		}

		char := board[r][c]
		nextNode, found := node.children[char]
		if !found {
			return
		}

		visit[[2]int{r, c}] = true
		word += string(char)
		if nextNode.isWord {
			wordSet[word] = true
		}

		dfs(r+1, c, nextNode, word)
		dfs(r-1, c, nextNode, word)
		dfs(r, c+1, nextNode, word)
		dfs(r, c-1, nextNode, word)

		visit[[2]int{r, c}] = false
	}

	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			dfs(r, c, root, "")
		}
	}

	for word := range wordSet {
		res = append(res, word)
	}
	return res
